#!/usr/bin/env python3
import os
import sys
import json
import time
import urllib.request
import urllib.error

API_BASE = os.environ.get("API_BASE", "http://127.0.0.1:8080").rstrip("/")
USER_AGENT = "SyncClient/1.0"
RETRYABLE_STATUS_CODES = {408, 429, 500, 502, 503, 504}


def _post_json(path: str, payload: dict, timeout: int = 30) -> dict:
    url = f"{API_BASE}{path}"
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=data,
        headers={"Content-Type": "application/json", "User-Agent": USER_AGENT},
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        body = resp.read().decode("utf-8")
        return json.loads(body) if body else {}


def _post_json_with_retries(path: str, payload: dict, timeout: int = 30, attempts: int = 5) -> dict:
    """POST JSON and retry transient failures/explicit rate limits."""
    for attempt in range(1, attempts + 1):
        try:
            return _post_json(path, payload, timeout=timeout)
        except urllib.error.HTTPError as exc:
            retryable = exc.code in RETRYABLE_STATUS_CODES
            if not retryable or attempt == attempts:
                raise

            retry_after = exc.headers.get("Retry-After")
            try:
                delay = float(retry_after) if retry_after else None
            except ValueError:
                delay = None
            if delay is None:
                delay = min(8.0, 0.5 * (2 ** (attempt - 1)))

            print(
                f"Request to {path} failed with HTTP {exc.code}; "
                f"retrying in {delay:.2f}s ({attempt}/{attempts})",
                file=sys.stderr,
                flush=True,
            )
            time.sleep(delay)
        except urllib.error.URLError as exc:
            if attempt == attempts:
                raise
            delay = min(8.0, 0.5 * (2 ** (attempt - 1)))
            print(
                f"Request to {path} failed: {exc}; "
                f"retrying in {delay:.2f}s ({attempt}/{attempts})",
                file=sys.stderr,
                flush=True,
            )
            time.sleep(delay)

    raise RuntimeError("unreachable retry state")


def post_webhook(record_id: int) -> dict:
    return _post_json_with_retries("/webhook", {"record_id": record_id}, timeout=10)


def post_bulk_response(record_ids: list) -> dict:
    if len(record_ids) > 100:
        raise ValueError("/bulk_sync supports at most 100 record_ids per request")
    return _post_json_with_retries("/bulk_sync", {"record_ids": record_ids}, timeout=30)


def post_bulk(record_ids: list) -> list:
    """Compatibility helper: return the API's synced list, as before."""
    res = post_bulk_response(record_ids)
    if isinstance(res, dict):
        synced = res.get("synced", [])
        return synced if isinstance(synced, list) else []
    return []


def _write_per_record_results(out, record_ids: list, response: dict) -> None:
    """
    Preserve the historical JSONL shape of one line per record while using the
    bulk endpoint. If the API returns a per-record `synced` list, write those
    entries; otherwise write a compact success entry for each requested id.
    """
    synced = response.get("synced") if isinstance(response, dict) else None

    if isinstance(synced, list) and len(synced) == len(record_ids):
        for rid, item in zip(record_ids, synced):
            if isinstance(item, dict):
                line = dict(item)
                line.setdefault("record_id", rid)
                line.setdefault("bulk", True)
            else:
                line = {"record_id": item, "bulk": True}
            out.write(json.dumps(line) + "\n")
    else:
        for rid in record_ids:
            out.write(json.dumps({"record_id": rid, "bulk": True, "synced": True}) + "\n")


def run_selftest():
    print("Running analytics sync selftest (3 records)...")
    out_file = "/tmp/selftest_synced.jsonl"
    with open(out_file, "w") as f:
        for rid in [201, 202, 203]:
            res = post_webhook(rid)
            f.write(json.dumps(res) + "\n")
            f.flush()
            time.sleep(0.15)  # Safe throttle (6.6 RPS < 10 RPS limit)
    print(f"Selftest complete. Saved to {out_file}")
    return 0


def run_sync():
    print("Starting sync of 1000 historical records...")
    out_file = "/tmp/synced_records.jsonl"

    # /bulk_sync supports up to 100 ids per request and 5 requests/second.
    # 1000 records -> 10 requests, comfortably inside the 3 minute window.
    batch_size = 100
    min_request_interval = 0.22  # conservative spacing for the 5 RPS limit
    last_request_started = 0.0
    total_synced = 0

    with open(out_file, "w") as f:
        for start in range(1, 1001, batch_size):
            record_ids = list(range(start, min(start + batch_size, 1001)))

            elapsed = time.monotonic() - last_request_started
            if last_request_started and elapsed < min_request_interval:
                time.sleep(min_request_interval - elapsed)

            last_request_started = time.monotonic()
            res = post_bulk_response(record_ids)
            _write_per_record_results(f, record_ids, res)
            f.flush()

            total_synced += len(record_ids)
            print(f"Synced {total_synced}/1000 records", flush=True)

    print(f"Sync complete. Saved to {out_file}")
    return 0


def main():
    if "--selftest" in sys.argv:
        sys.exit(run_selftest())
    else:
        sys.exit(run_sync())


if __name__ == "__main__":
    main()
